.top-strip .title { font-weight: 700;text-align:right; }
.top-strip .center { text-align: center; font-style: italic; font-size: 10px;text-align:right; }
.top-strip .right { text-align: right; font-weight: 700; }

/* ---------- IRN / Ack / QR strip ---------- */

.irn-strip td { border: none; }
.irn-strip .irn-left { width: 60%; line-height: 15px;vertical-align:middle !important; }
.irn-strip .irn-left b { display: inline-block; width: 70px; vertical-align: middle; }
.irn-strip .qr-cell { width: 25%; text-align: center; }
.irn-strip .qr-cell img { width: 90px; height: 90px; }

/* ---------- Main details table (seller/consignee/buyer + invoice meta) ---------- */
.main-table td { border: 1px solid #000; }
.main-table { border-top: none;border-bottom :none; }

.party-cell { width: 55%;paddig:0 }
.party-block { padding-bottom: 4px; }
.party-block:not(:last-child) { border-bottom: 1px solid #000; padding: 4px; }
.party-block { padding: 4px; }
.party-block .company-name { font-weight: 700; font-size: 12px; }
/*.party-block .block-title { font-weight: 700; text-decoration: underline; }*/

.meta-label { font-weight: 600; color: #333; }
.meta-value { font-weight: 700; }

/* ---------- Items table ---------- */
.items-table { margin-top: 0; border-top :none !important; }
.items-table td, .items-table th {
    border-left: 1px solid #000;
    border-right: 1px solid #000;
   
    
}


.items-table thead tr { border-top: 1px solid #000; border-bottom: 1px solid #000;background:transparent; }
.items-table thead th { text-align: center; font-weight: 700; border-bottom: 1px solid #000;background:transparent !important;border-top:none !important; }
.items-table tbody tr:last-child td { border-bottom: none; }
.items-table .num { text-align: right; }
.items-table .ctr { text-align: center; }
.items-table .tax-row td { border-top: none; padding-top: 0; padding-bottom: 0; }
.items-table .total-row td { border-top: 1px solid #000; font-weight: 700;border-bottom:1px solid #000 !important; }

/* ---------- Amount in words ---------- */
.words-row td { border: 1px solid #000; border-top: none;border-bottom:none; }
.words-row .label { font-weight: 700; }

/* ---------- HSN summary table ---------- */
.hsn-table { border-top: none;background:none !important; }
.hsn-table td, .hsn-table th { border: 1px solid #000; text-align: center;background:transparent !important; }
.hsn-table .num { text-align: right; }
.hsn-table tfoot td { font-weight: 700; }

/* ---------- Tax amount in words / remarks / declaration / signature ---------- */
.bottom-table td { border: 1px solid #000; border-top: none; }
.bottom-table .no-border-top { border-top: none; }
.remarks-cell { width: 55%;border-top:none !important; }
.signature-cell { text-align: right; vertical-align: bottom;border-top:1px solid #000 !important;border-bottom:none;   }
.signature-cell .sign-space { height: 55px;}
.declaration-cell { font-size: 10px; }

.footer-note {
    text-align: center;
    font-size: 10px;
