}

/* Letterhead Container */
.letterhead-container {
    width: 100%;
    margin-bottom: 6px;
}

.letterhead-container table {
    width: 100% !important;
}

/* Document Title */
.doc-title {
    text-align: center;
    font-size: 14px;
    font-weight: 800;
    letter-spacing: 2px;
    color: #222;
    margin: 8px 0 10px 0;
}

/* Meta Box */
.meta-box-table {
    width: 100%;
    background-color: #f2f6fc;
    border-radius: 4px;
    border-collapse: collapse;
    padding: 6px;
    margin-bottom: 10px;
}

.meta-box-table td {
    border: none !important;
}

.inner-meta {
    width: 100%;
    border-collapse: collapse;
}

.inner-meta td {
    padding: 2.5px 5px;
    font-size: 10.5px;
    vertical-align: top;
}

.inner-meta .lbl {
    font-weight: 700;
    width: 32%;
    color: #222;
}

.inner-meta .val {
    color: #333;
}

/* Bill To / Ship To Side-by-Side Cards */
.address-grid {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 12px;
}

.address-grid td {
    border: none !important;
    padding: 0;
}

.address-card {
    border: 1px solid #dcdcdc;
    border-radius: 3px;
    overflow: hidden;
    background-color: #ffffff;
}

.address-header {
    background-color: #1e5ba3 !important;
    color: #ffffff !important;
    font-weight: 700;
    font-size: 11px;
    padding: 4px 8px;
    letter-spacing: 0.5px;
}

.address-body {
    padding: 6px 8px;
    font-size: 10px;
    line-height: 1.4;
    color: #333;
}

/* Items Table */
.items-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 6px;
}

.items-table thead,
.items-table th {
    background-color: #1e5ba3 !important;
    color: #ffffff !important;
    font-size: 10px;
    font-weight: 700;
    padding: 5px 4px;
    border: 1px solid #14447d !important;
    text-align: center;
}

.items-table td {
    border: 1px solid #d3d9df;
    padding: 4px 5px;
    font-size: 10px;
    color: #111;
}

/* Totals Table */
.totals-table {
    width: 42%;
    margin-left: auto;
    border-collapse: collapse;
    margin-top: 4px;
    margin-bottom: 10px;
}

.totals-table td {
    padding: 3px 6px;
    font-size: 10.5px;
}

.totals-table .lbl {
    text-align: right;
    font-weight: 700;
    width: 60%;
}

.totals-table .val {
    text-align: right;
    width: 40%;
}

/* Grand Total Row */
.totals-table .grand-total-row td {
    font-size: 11.5px;
    font-weight: 900;
    color: #000000 !important;
    border-top: 1.5px solid #000000;
    border-bottom: 2px solid #000000;
    padding-top: 5px;
    padding-bottom: 5px;
}

/* Terms & Signature */
.terms-content p {
    margin: 2px 0;
}

.terms-content ol, 
.terms-content ul {
    margin: 2px 0 0 16px;
    padding: 0;
}

.sign-header {
    background-color: #1e5ba3 !important;
    color: #ffffff !important;
    font-weight: 700;
    font-size: 10.5px;
    padding: 4px;
    border-radius: 2px;
}

